SELECT ?p ?series WHERE {
  ?z a brick:Zone ; rdfs:label ?lbl .
  ?p brick:hasParent ?z ; a brick:ElectricPowerSensor ; a brick:LightingSensor .
  ?p ref:hasTimeseriesId ?series .
  FILTER (?lbl IN ("Perimeter_mid_ZN_4","Perimeter_mid_ZN_2"))
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  FILTER (?lbl IN ("Perimeter_mid_ZN_4","Perimeter_mid_ZN_2"))
}

SELECT ?ps ?lbl ?series WHERE {
  ?ps a brick:Power_Sensor .
  ?ps rdfs:label ?lbl .
  ?ps brick:hasParent ?z .
  ?z rdfs:label ?zl .
  FILTER (?zl IN ("Perimeter_mid_ZN_2","Perimeter_mid_ZN_4"))
  OPTIONAL { ?ps ref:hasTimeseriesId ?series }
}

SELECT ?ps ?plabel ?zl ?series WHERE {
  ?ps a brick:Power_Sensor .
  ?ps rdfs:label ?plabel .
  ?ps brick:hasParent ?z .
  OPTIONAL { ?z rdfs:label ?zl }
  OPTIONAL { ?ps ref:hasTimeseriesId ?series }
}

SELECT ?ps ?lbl ?p2 ?o WHERE {
  ?ps a brick:Electric_Power_Sensor .
  OPTIONAL { ?ps rdfs:label ?lbl }
  OPTIONAL { ?ps ?p2 ?o }
}

